const $=s=>document.querySelector(s),COLORS=['#51d7ff','#ff5d7d','#ffd34e','#78e08f','#b58cff','#ff934f','#f47bd2','#47e0c0','#e9eef7','#687cff'];let selected=COLORS[0],ws,state,priv,myId,keys={},seq=0,last=0,cam={x:0,y:0},mapOpen=false;
const stations=[['t1',230,210,'multiple-choice'],['t2',620,190,'matchmaker'],['t3',1090,190,'chronology'],['t4',1570,210,'classification'],['t5',1980,210,'systems'],['emergency',1100,700,'meeting'],['lights',620,1160,'repair'],['comms',620,250,'repair'],['reactorA',1500,1130,'repair'],['reactorB',1650,1240,'repair']];
const rooms=[['Bridge',60,60,340,350],['Communications',460,60,340,290],['Observation Deck',860,60,480,290],['Laboratory',1400,60,340,350],['Medical Bay',1800,60,340,350],['Cargo Bay',60,1040,340,340],['Engine Room',460,940,340,440],['Central Hub',860,400,480,600],['Reactor',1400,940,340,440]];
$('#colors').innerHTML=COLORS.map((c,i)=>`<button style="background:${c}" data-c="${c}" class="${i?'':'selected'}" aria-label="Color ${i+1}"></button>`).join('');$('#colors').onclick=e=>{if(e.target.dataset.c){selected=e.target.dataset.c;document.querySelectorAll('.colors button').forEach(x=>x.classList.toggle('selected',x===e.target))}};
function connect(){const param=new URLSearchParams(location.search).get('server');if(param)localStorage.suspectServer=param;const url=param||localStorage.suspectServer||(location.protocol==='file:'?'ws://localhost:8080/ws':`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);ws=new WebSocket(url);ws.onmessage=e=>handle(JSON.parse(e.data));ws.onclose=()=>{toast('Connection lost — reconnecting…');setTimeout(()=>{connect();},1200)}}
const send=x=>ws?.readyState===1&&ws.send(JSON.stringify(x));function join(){let code=$('#code').value.trim().toUpperCase(),nickname=$('#nick').value.trim(),saved=JSON.parse(localStorage.suspectSession||'null');send(saved&&saved.code===code?{type:'join',code,reconnectToken:saved.token}:{type:'join',code,nickname,color:selected})}$('#join').onclick=join;
function handle(m){if(m.type==='joined'){myId=m.id;localStorage.suspectSession=JSON.stringify({code:m.code,token:m.reconnectToken});$('#menu').classList.add('hidden');$('#lobby').classList.remove('hidden');$('#roomCode').textContent=m.code}else if(m.type==='private'){let changed=priv?.role!==m.role;priv=m;if(changed&&m.role)revealRole()}else if(m.type==='state'){let prior=state?.phase;state=m;renderState();if(m.phase==='playing'&&prior!=='playing')showGame();if(m.phase==='meeting')meeting();if(m.phase==='ended')ending()}else if(m.type==='error'){$('#error').textContent=m.message;toast(m.message)}else if(m.type==='toast')toast(m.message)}
function renderState(){if(!state)return;$('#roster').innerHTML=state.players.map(p=>`<div class="crew"><i style="background:${p.color}"></i><b>${safe(p.nickname)}</b><small>${p.ready?'READY':'NOT READY'}</small></div>`).join('');$('#progress').style.width=(state.taskProgress.ratio*100)+'%';$('#phase').textContent=state.sabotage?`${state.sabotage.type.toUpperCase()} SABOTAGE`:state.phase.toUpperCase();if(priv)$('#taskList').innerHTML=priv.tasks.map(q=>`<div class="task ${priv.completed.includes(q.id)?'done':''}">${priv.completed.includes(q.id)?'✓':'◇'} ${safe(q.prompt)}</div>`).join('');$('#ability').classList.toggle('hidden',priv?.role!=='impostor')}
$('#ready').onclick=()=>{let p=state?.players.find(x=>x.id===myId);send({type:'ready',ready:!p?.ready})};function showGame(){$('#lobby').classList.add('hidden');$('#game').classList.remove('hidden');resize();requestAnimationFrame(loop)}
function revealRole(){$('#roleReveal').classList.remove('hidden');$('#roleReveal').innerHTML=`<div class="dialog roleCard ${priv.role}"><div class="eyebrow">CLASSIFIED ASSIGNMENT</div><h1>${priv.role.toUpperCase()}</h1><p>${priv.role==='impostor'?'Blend in. Sabotage the Meridian.':'Finish the missions. Find the infiltrator.'}</p><button>BEGIN</button></div>`;$('#roleReveal button').onclick=()=>$('#roleReveal').classList.add('hidden')}
const canvas=$('#world'),ctx=canvas.getContext('2d');function resize(){canvas.width=innerWidth*devicePixelRatio;canvas.height=innerHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}addEventListener('resize',resize);addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='e')interact();if(e.key.toLowerCase()==='r')report();if(e.key.toLowerCase()==='m')mapOpen=!mapOpen});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function loop(t){if($('#game').classList.contains('hidden'))return;let p=state?.players.find(x=>x.id===myId);if(p&&state.phase==='playing'&&t-last>60){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dy)send({type:'move',dx,dy,seq:++seq});last=t}draw(p,t);requestAnimationFrame(loop)}
function draw(me,t){let w=innerWidth,h=innerHeight;if(me){cam.x+=(me.x-cam.x-w/2)*.12;cam.y+=(me.y-cam.y-h/2)*.12}ctx.fillStyle='#07111e';ctx.fillRect(0,0,w,h);ctx.save();if(mapOpen){let s=Math.min(w/2250,h/1500);ctx.translate((w-2200*s)/2,(h-1450*s)/2);ctx.scale(s,s)}else ctx.translate(-cam.x,-cam.y);ctx.fillStyle='#0d2035';ctx.fillRect(40,40,2120,1370);for(const [n,x,y,rw,rh] of rooms){ctx.fillStyle='#132d47';ctx.fillRect(x,y,rw,rh);ctx.strokeStyle='#345573';ctx.lineWidth=4;ctx.strokeRect(x,y,rw,rh);ctx.fillStyle='#6e91aa';ctx.font='700 20px system-ui';ctx.textAlign='center';ctx.fillText(n.toUpperCase(),x+rw/2,y+35)}ctx.strokeStyle='#203e58';ctx.lineWidth=24;for(const x of [420,820,1360,1760]){ctx.beginPath();ctx.moveTo(x,40);ctx.lineTo(x,1410);ctx.stroke()}for(const [id,x,y,type] of stations){ctx.fillStyle=type==='meeting'?'#ffca4c':type==='repair'?'#ff6d77':'#43d9ff';ctx.fillRect(x-22,y-18,44,36);ctx.fillStyle='#07111e';ctx.fillRect(x-12,y-10,24,14)}for(const b of state?.bodies||[]){if(!b.reported){ctx.fillStyle='#ff496b';ctx.beginPath();ctx.arc(b.x,b.y,22,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.fillRect(b.x-4,b.y-7,26,10)}}for(const p of state?.players||[])drawPlayer(p,t);ctx.restore();if(mapOpen){ctx.fillStyle='#fff';ctx.font='700 18px system-ui';ctx.fillText('MAP · press M to close',w/2,28)}}
function drawPlayer(p,t){ctx.save();ctx.translate(p.x,p.y);if(!p.alive)ctx.globalAlpha=.38;let bob=Math.sin(t/180+p.x)*2;ctx.fillStyle=p.color;ctx.beginPath();ctx.roundRect(-22,-28+bob,44,52,16);ctx.fill();ctx.fillStyle='#bff2ff';ctx.beginPath();ctx.ellipse(5,-12+bob,15,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#253b56';ctx.beginPath();ctx.arc(10,-14+bob,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle=p.color;ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(-10,18);ctx.lineTo(-13,30+Math.sin(t/100)*3);ctx.moveTo(10,18);ctx.lineTo(13,30-Math.sin(t/100)*3);ctx.stroke();if(priv?.impostors?.includes(p.id)){ctx.strokeStyle='#ff496b';ctx.lineWidth=2;ctx.strokeRect(-27,-34,54,67)}ctx.fillStyle='white';ctx.font='600 13px system-ui';ctx.textAlign='center';ctx.fillText(p.nickname,0,-40);ctx.restore()}
function nearest(){let p=state.players.find(x=>x.id===myId);return stations.map(s=>({s,d:Math.hypot(p.x-s[1],p.y-s[2])})).sort((a,b)=>a.d-b.d)[0]}
function interact(){if(!state||state.phase!=='playing')return;let n=nearest();if(n.d>110)return toast('Move closer to a console');let [id,x,y,type]=n.s;if(type==='meeting')return send({type:'meeting'});if(type==='repair'&&state.sabotage)return send({type:'repair',stationId:id});let q=priv?.tasks.find(x=>x.type===type&&!priv.completed.includes(x.id));if(q)taskDialog(q);else toast('No mission available here')}
function taskDialog(q){let d=document.createElement('div');d.className='dialog';let body='';if(q.type==='multiple-choice'||q.type==='systems')body=q.options.map(x=>`<button class="choice" data-a="${safe(x)}">${safe(x)}</button>`).join('');else if(q.type==='chronology')body=`<p>Enter the items in chronological order, separated by |</p><input id="taskAnswer" value="${q.items.join(' | ')}"><button id="submitTask">VERIFY ORDER</button>`;else{let vals=q.type==='matchmaker'?q.options:q.categories;body=q.items.map(x=>`<label>${safe(x)}<select data-key="${safe(x)}">${vals.map(v=>`<option>${safe(v)}</option>`).join('')}</select></label>`).join('')+`<button id="submitTask">VERIFY</button>`}d.innerHTML=`<button class="close">×</button><h2>${safe(q.prompt)}</h2>${body}`;openModal(d);d.querySelector('.close').onclick=closeModal;d.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{send({type:'task',taskId:q.id,answer:b.dataset.a});closeModal()});d.querySelector('#submitTask')?.addEventListener('click',()=>{let answer=q.type==='chronology'?d.querySelector('#taskAnswer').value.split('|').map(x=>x.trim()):Object.fromEntries([...d.querySelectorAll('select[data-key]')].map(s=>[s.dataset.key,s.value]));send({type:'task',taskId:q.id,answer});closeModal()})}
function report(){let p=state?.players.find(x=>x.id===myId),b=state?.bodies.filter(x=>!x.reported).sort((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)-Math.hypot(p.x-b.x,p.y-b.y))[0];if(b)send({type:'report',bodyId:b.id});else toast('No body nearby')}
function meeting(){if($('#modal').dataset.kind==='meeting')return;let d=document.createElement('div');d.className='dialog';d.innerHTML=`<div class="eyebrow">MEETING CALLED</div><h2>${safe(state.meeting.reason)}</h2><p>Discuss in person. Voting opens after the timer.</p><div id="voteCards"></div>`;$('#modal').dataset.kind='meeting';openModal(d);let render=()=>{if(!state||state.phase!=='meeting')return closeModal();let open=state.meeting.stage==='voting',voted=state.meeting.voted.includes(myId);d.querySelector('#voteCards').innerHTML=state.players.filter(p=>p.alive).map(p=>`<button class="card" data-v="${p.id}" ${!open||voted?'disabled':''}>${safe(p.nickname)}</button>`).join('')+`<button class="card" data-v="skip" ${!open||voted?'disabled':''}>SKIP VOTE</button>`;d.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>send({type:'vote',target:b.dataset.v}));if(state.phase==='meeting')setTimeout(render,500)};render()}
function ending(){let d=document.createElement('div');d.className='dialog roleCard';d.innerHTML=`<div class="eyebrow">MISSION COMPLETE</div><h1>${state.winner.team.toUpperCase()} WIN</h1><p>${safe(state.winner.reason)}</p><h3>Teacher can return the crew to the lobby for a rematch.</h3>`;openModal(d)}
$('#interact').onclick=interact;$('#report').onclick=report;$('#mapBtn').onclick=()=>mapOpen=!mapOpen;$('#ability').onclick=()=>{let d=document.createElement('div');d.className='dialog';d.innerHTML='<h2>Impostor systems</h2><button data-s="lights">LIGHTS OUT</button> <button data-s="comms">JAM COMMS</button> <button data-s="reactor">REACTOR EMERGENCY</button>';openModal(d);d.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{send({type:'sabotage',sabotage:b.dataset.s});closeModal()})};function openModal(d){$('#modal').innerHTML='';$('#modal').append(d);$('#modal').classList.remove('hidden')}function closeModal(){$('#modal').classList.add('hidden');$('#modal').dataset.kind=''}function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));connect();

